use xiom.io;

fn main() -> Int {
  let player_name: Option[Str] = None;
  let final_name = player_name.unwrap_or("Player1");
  io.println(final_name.to_str());

  let player_name2 = Some("DragonSlayer");
  let final_name2 = player_name2.unwrap_or("Player1");
  io.println(final_name2.to_str());
  return 0;
}
